import { launch } from '/www/server/nodejs/v22.22.2/lib/node_modules/cloakbrowser/dist/index.js';

const browser = await launch({ headless: true });
const page = await browser.newPage();

// 设置User-Agent为桌面浏览器
await page.setExtraHTTPHeaders({
  'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'
});

await page.goto('https://mp.weixin.qq.com/s/mhqxzEvh-WvJteo5ZzYO0w', { waitUntil: 'networkidle0', timeout: 30000 });

// 等待内容加载
await page.waitForTimeout(3000);

// 获取页面文本内容
const text = await page.evaluate(() => {
  const article = document.querySelector('#js_content') || document.querySelector('.article-content') || document.querySelector('.rich_media_content');
  if (article) return article.innerText;
  return document.body.innerText.substring(0, 5000);
});

console.log('=== Page Content ===');
console.log(text);
console.log('=== End ===');

await browser.close();

